(async()=>{const same=await document.hasStorageAccess();const frame=await new Promise((resolve,reject)=>{const url=new URL('/frame',location.href);url.hostname='localhost';const f=document.createElement('iframe');const handler=e=>{if(e.source!==f.contentWindow)return;window.removeEventListener('message',handler);f.remove();resolve(e.data)};window.addEventListener('message',handler);f.onerror=()=>reject(Error('frame'));f.src=url.href;document.body.append(f)});return {same,frame}})()
